@section('scripts')
<script>
const smsEvents=@json($events),smsSamples=@json(config('sms_events.samples',[])),smsTemplates=@json($templatePayload);
const modal=document.getElementById('template-modal'),form=document.getElementById('template-form'),eventEl=document.getElementById('template-event'),bodyEl=document.getElementById('template-body');
function openTemplate(data=null){form.reset();document.getElementById('template-active').checked=true;document.getElementById('template-method').value=data?'PUT':'POST';form.action=data?`{{ url('/admin/sms/templates') }}/${data.id}`:`{{ route('admin.sms.templates.store') }}`;document.getElementById('template-modal-title').textContent=data?'ویرایش الگو':'الگوی جدید';if(data){eventEl.value=data.event_key;document.getElementById('template-name').value=data.name;bodyEl.value=data.body;document.getElementById('template-active').checked=data.is_active;document.getElementById('template-default').checked=data.is_default}modal.hidden=false;updateComposer()}
function updateComposer(){const text=bodyEl.value,unicode=/[^\x00-\x7F]/.test(text),single=unicode?70:160,multi=unicode?67:153,parts=text.length<=single?(text.length?1:0):Math.ceil(text.length/multi);document.getElementById('sms-char-count').textContent=`${text.length} کاراکتر`;document.getElementById('sms-part-count').textContent=`${parts} بخش`;document.getElementById('sms-encoding').textContent=unicode?'یونیکد':'لاتین';document.getElementById('sms-variable-list').innerHTML=(smsEvents[eventEl.value]?.variables||[]).map(v=>`<button type="button" class="sms-var" data-var="${v}">{${v}}</button>`).join('');document.getElementById('sms-preview-text').textContent=text.replace(/\{([a-z_]+)\}/gi,(_,k)=>smsSamples[k]??`{${k}}`)||'—'}
document.getElementById('new-template').onclick=()=>openTemplate();document.querySelectorAll('.sms-edit-template').forEach(b=>b.onclick=()=>openTemplate(smsTemplates.find(item=>String(item.id)===b.dataset.templateId)));document.querySelectorAll('.sms-modal-close').forEach(b=>b.onclick=()=>modal.hidden=true);eventEl.onchange=updateComposer;bodyEl.oninput=updateComposer;document.getElementById('sms-variable-list').onclick=e=>{if(!e.target.dataset.var)return;const token=`{${e.target.dataset.var}}`,start=bodyEl.selectionStart;bodyEl.value=bodyEl.value.slice(0,start)+token+bodyEl.value.slice(bodyEl.selectionEnd);bodyEl.focus();bodyEl.selectionStart=bodyEl.selectionEnd=start+token.length;updateComposer()};
const testModal=document.getElementById('test-modal');document.querySelectorAll('.sms-test-open').forEach(b=>b.onclick=()=>{document.getElementById('test-template-name').textContent=b.dataset.name;document.getElementById('test-form').action=`{{ url('/admin/sms/templates') }}/${b.dataset.id}/test`;testModal.hidden=false});document.querySelectorAll('.sms-test-close').forEach(b=>b.onclick=()=>testModal.hidden=true);
</script>
